function buildPrescriptionQuiz(mode){
  const p=String(mode).split(':');
  const kind=p[1]||'knowledge',cat=p.slice(2).join(':')||weakestSkill();
  const same=QUESTION_BANK.filter(q=>q.cat===cat);
  let pool=[];
  if(kind==='calc'){
    pool=shuffled(same.filter(q=>questionMatchesKeywords(q,RX_CALC_KEYWORDS)));
    if(pool.length<6) pool=[...pool,...shuffled(QUESTION_BANK.filter(q=>questionMatchesKeywords(q,RX_CALC_KEYWORDS)&&!pool.some(x=>x.id===q.id)))];
    return padQuizPool(pool,cat,8);
  }
  if(kind==='read'){
    const words=['最も適切','適切','未満','以上','次に','主な','一般に','どれ'];
    return padQuizPool(shuffled(same.filter(q=>words.some(w=>q.q.includes(w)))),cat,8);
  }
  if(kind==='contrast'){
    pool=shuffled(same.filter(q=>questionMatchesKeywords(q,RX_CONTRAST_KEYWORDS)));
    if(pool.length<6) pool=[...pool,...shuffled(QUESTION_BANK.filter(q=>questionMatchesKeywords(q,RX_CONTRAST_KEYWORDS)&&!pool.some(x=>x.id===q.id)))];
    return padQuizPool(pool,cat,8);
  }
  if(kind==='repeat'){
    const ids=new Set(repeatedWrongQuestions().map(x=>x.q.id));
    return padQuizPool(shuffled(QUESTION_BANK.filter(q=>ids.has(q.id))),cat,8);
  }
  if(kind==='speed') return padQuizPool(shuffled(same),cat,10);
  return padQuizPool(shuffled(same),cat,8);
}
